mapper.select:
SELECT COUNT(*)
FROM medications
WHERE medication_id = #{medicationId}

SELECT cabinet_id
FROM cabinet_medications
WHERE user_id = #{userId}
  AND medication_id = #{medicationId}
  AND ROWNUM = 1

SELECT routine_id
FROM routine_medications
WHERE user_id = #{userId}
  AND supplement_name = #{supplementName}
  AND ROWNUM = 1

WITH ALL_CALENDAR AS ( /* 수동 등록 일정 */ SELECT TO_CHAR(s.scheduled_at, 'YYYY-MM-DD') AS scheduleDate, MAX(CASE WHEN s.prescription_id IS NOT NULL THEN 1 ELSE 0 END) AS hasPrescription, MAX(CASE WHEN s.cabinet_id IS NOT NULL THEN 1 ELSE 0 END) AS hasRegular, MAX(CASE WHEN s.routine_id IS NOT NULL THEN 1 ELSE 0 END) AS hasSupplement FROM schedules s WHERE s.user_id = #{userId} AND TO_CHAR(s.scheduled_at, 'YYYY-MM') = #{yearMonth} GROUP BY TO_CHAR(s.scheduled_at, 'YYYY-MM-DD')
UNION ALL
/* 처방전 유효 기간 내 날짜 */ SELECT TO_CHAR(TRUNC(p.dispensed_date) + LEVEL - 1, 'YYYY-MM-DD') AS scheduleDate, 1 AS hasPrescription, 0 AS hasRegular, 0 AS hasSupplement FROM prescriptions p WHERE p.user_id = #{userId} AND TO_CHAR(TRUNC(p.dispensed_date) + LEVEL - 1, 'YYYY-MM') = #{yearMonth}
CONNECT BY LEVEL <= p.total_days AND PRIOR p.prescription_id = p.prescription_id AND PRIOR SYS_GUID() IS NOT NULL
) SELECT scheduleDate AS "scheduleDate", MAX(hasPrescription) AS "hasPrescription", MAX(hasRegular) AS "hasRegular", MAX(hasSupplement) AS "hasSupplement" FROM ALL_CALENDAR GROUP BY scheduleDate ORDER BY scheduleDate ASC

mapper.update:
UPDATE schedules
   SET taken_at = CASE WHEN #{isTaken} = 1 THEN (SYSDATE + (9/24)) ELSE NULL END
 WHERE schedule_id = #{scheduleId}

mapper.insert:
INSERT INTO schedules ( user_id, prescription_id, medication_id, scheduled_at, alarm_enabled, taken_at ) VALUES ( #{userId}, #{prescriptionId}, #{medicationId}, TO_DATE(#{scheduledDate} || ' ' || #{newTime}, 'YYYY-MM-DD HH24:MI'), NVL(#{alarmEnabled}, 1),
(SYSDATE + (9/24)) NULL
)

